DELETE FROM newsletter_confirmation_challenges WHERE created_at < datetime('now', '-30 days'); DELETE FROM newsletter_confirmation_delivery_state WHERE updated_at < datetime('now', '-30 days'); DELETE FROM newsletter_webhook_events WHERE created_at < datetime('now', '-90 days'); UPDATE newsletter_deliveries SET error_code = NULL, error_message = NULL WHERE updated_at < datetime('now', '-90 days'); DELETE FROM newsletter_deliveries WHERE send_id IN (SELECT id FROM newsletter_sends WHERE status IN ('completed','partial','failed') AND completed_at < datetime('now', '-24 months')); UPDATE newsletter_sends SET source_send_id = NULL WHERE source_send_id IN (SELECT id FROM newsletter_sends WHERE status IN ('completed','partial','failed') AND completed_at < datetime('now', '-24 months')); DELETE FROM newsletter_sends WHERE status IN ('completed','partial','failed') AND completed_at < datetime('now', '-24 months') AND NOT EXISTS (SELECT 1 FROM newsletter_deliveries d WHERE d.send_id = newsletter_sends.id); DELETE FROM newsletters WHERE ((status = 'sent' AND sent_at < datetime('now', '-24 months')) OR (status = 'failed' AND updated_at < datetime('now', '-24 months'))) AND NOT EXISTS (SELECT 1 FROM newsletter_sends s WHERE s.newsletter_id = newsletters.id);
